package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** A sheet's settings: the role each user name has on it, and its clerk limit, its floor, its cap, its terms
 *  (and any grade's own terms) and its late percent, its policy date and its period numbering from. The
 *  settings that carry a figure are dated: each value recorded is in force from its from-date. A claim's
 *  floor, late percent and terms are those in force on its date; the clerk limit and the cap those in
 *  force on the sheet's today. */
@Service
public class SettingService {

    /** The key prefix of a grade's own terms: terms-A, terms-B, terms-C. */
    private static final String GRADE_TERMS = "terms-";

    private final SheetService sheets;
    private final SheetRepository sheetRepository;
    private final SheetRoleRepository roles;
    private final SettingValueRepository values;
    private final Audit audit;

    public SettingService(SheetService sheets, SheetRepository sheetRepository, SheetRoleRepository roles,
            SettingValueRepository values, Audit audit) {
        this.sheets = sheets;
        this.sheetRepository = sheetRepository;
        this.roles = roles;
        this.values = values;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserAsc(sheetId);
    }

    /** The user's role on the sheet: clerk unless assigned another. */
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** The floor a sheet starts with: in force before the first from-date recorded for it. */
    public static final BigDecimal START_FLOOR = new BigDecimal("1.00");

    /** The late percent a sheet starts with. */
    public static final BigDecimal START_LATE_PCT = new BigDecimal("0.00");

    /** The terms a sheet starts with, in days. */
    public static final int START_TERMS = 14;

    /** The values recorded for the sheet's dated settings, by key, each list by from-date. */
    public Map<String, List<SettingValue>> dated(String sheetId) {
        Map<String, List<SettingValue>> byKey = new TreeMap<>();
        values.findBySheetIdOrderByKeyAscFromAsc(sheetId)
                .forEach(v -> byKey.computeIfAbsent(v.getKey(), k -> new ArrayList<>()).add(v));
        return byKey;
    }

    /** The value recorded for a dated setting that is in force on a date: the one with the latest
     *  from-date on or before it; empty before every from-date (the sheet's starting value applies). */
    private Optional<SettingValue> inForce(String sheetId, String key, LocalDate on) {
        return values.findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(sheetId, key, on);
    }

    /** The sheet's clerk limit in force on its today; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return inForce(sheetId, "clerk-limit", sheets.today(sheetId)).map(SettingValue::getValue).orElse(null);
    }

    /** The sheet's floor in force on a date: the least the live due of a claim of that date can be. */
    public BigDecimal floor(String sheetId, LocalDate on) {
        return inForce(sheetId, "floor", on).map(SettingValue::getValue).orElse(START_FLOOR);
    }

    /** The sheet's cap in force on its today: the most a person's due-total can be; null when there is none. */
    public BigDecimal cap(String sheetId) {
        return inForce(sheetId, "cap", sheets.today(sheetId)).map(SettingValue::getValue).orElse(null);
    }

    /** A person's due-total held to the sheet's cap; a due-total of none (n/a) is not capped. */
    public BigDecimal capped(String sheetId, BigDecimal dueTotal) {
        BigDecimal cap = cap(sheetId);
        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
    }

    /** The sheet's terms in days in force on a date: a claim of that date is due by its date plus them. */
    public int terms(String sheetId, LocalDate on) {
        return inForce(sheetId, "terms", on).map(v -> v.getValue().intValue()).orElse(START_TERMS);
    }

    /** The grades' own terms in force on a date, by grade; a grade not listed takes the sheet's terms. */
    public Map<String, Integer> gradeTerms(String sheetId, LocalDate on) {
        Map<String, Integer> byGrade = new LinkedHashMap<>();
        dated(sheetId).forEach((key, recorded) -> {
            if (!key.startsWith(GRADE_TERMS)) {
                return;
            }
            recorded.stream().filter(v -> !v.getFrom().isAfter(on)).reduce((a, b) -> b)
                    .ifPresent(v -> byGrade.put(key.substring(GRADE_TERMS.length()), v.getValue().intValue()));
        });
        return byGrade;
    }

    /** The terms in days a claim of the grade dated on a date takes: the grade's own in force then,
     *  else the sheet's. */
    public int termsFor(String sheetId, String grade, LocalDate on) {
        if (grade == null) {
            return terms(sheetId, on);
        }
        return inForce(sheetId, GRADE_TERMS + grade, on).map(v -> v.getValue().intValue())
                .orElseGet(() -> terms(sheetId, on));
    }

    /** The sheet's late percent in force on a date: an overdue claim of that date's due gains it of its
     *  figure for every full 30 days it is overdue. */
    public BigDecimal latePct(String sheetId, LocalDate on) {
        return inForce(sheetId, "late-pct", on).map(SettingValue::getValue).orElse(START_LATE_PCT);
    }

    /** The sheet's policy date as set; null when it is blank (the sheet's today applies). */
    public LocalDate policyDateSet(String sheetId) {
        return sheets.load(sheetId).getPolicyDate();
    }

    /** The sheet's policy date in force: as set, else the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = policyDateSet(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    /** The sheet's period numbering from; null when it is blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        return sheets.load(sheetId).getPeriodNumberingFrom();
    }

    /** How a claim dated on the given date rounds: half up before the policy date, half to even on or
     *  after it. */
    public RoundingMode roundingOn(String sheetId, LocalDate date) {
        return date.isBefore(policyDate(sheetId)) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** Assign a user name a role on the sheet. */
    @Transactional
    public SheetRole setRole(String sheetId, String by, String user, Role role) {
        sheets.lock(sheetId);
        SheetRole saved = roles.findBySheetIdAndUser(sheetId, user)
                .map(existing -> {
                    existing.setRole(role);
                    return existing;
                })
                .orElseGet(() -> new SheetRole(sheetId, user, role));
        saved = roles.saveAndFlush(saved);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role.label());
        return saved;
    }

    /** Record the sheet's clerk limit from a date (null for the sheet's today); a null limit records none. */
    @Transactional
    public SettingValue setClerkLimit(String sheetId, String by, BigDecimal limit, LocalDate from) {
        return record(sheetId, by, "clerk-limit", limit != null ? limit.setScale(2, RoundingMode.UNNECESSARY) : null, from);
    }

    /** Record the sheet's floor from a date (null for the sheet's today). */
    @Transactional
    public SettingValue setFloor(String sheetId, String by, BigDecimal floor, LocalDate from) {
        return record(sheetId, by, "floor", floor.setScale(2, RoundingMode.UNNECESSARY), from);
    }

    /** Record the sheet's cap from a date (null for the sheet's today); a null cap records none. */
    @Transactional
    public SettingValue setCap(String sheetId, String by, BigDecimal cap, LocalDate from) {
        return record(sheetId, by, "cap", cap != null ? cap.setScale(2, RoundingMode.UNNECESSARY) : null, from);
    }

    /** Record the sheet's terms from a date (null for the sheet's today). */
    @Transactional
    public SettingValue setTerms(String sheetId, String by, int terms, LocalDate from) {
        return record(sheetId, by, "terms", BigDecimal.valueOf(terms), from);
    }

    /** Record a grade's own terms on the sheet from a date (null for the sheet's today). */
    @Transactional
    public SettingValue setGradeTerms(String sheetId, String by, String grade, int terms, LocalDate from) {
        return record(sheetId, by, GRADE_TERMS + grade, BigDecimal.valueOf(terms), from);
    }

    /** Record the sheet's late percent from a date (null for the sheet's today). */
    @Transactional
    public SettingValue setLatePct(String sheetId, String by, BigDecimal latePct, LocalDate from) {
        return record(sheetId, by, "late-pct", latePct.setScale(2, RoundingMode.UNNECESSARY), from);
    }

    /** Record a dated setting's value from a date, the sheet's today when none is given, keeping the
     *  values already recorded; one already recorded from that date is replaced. */
    private SettingValue record(String sheetId, String by, String key, BigDecimal value, LocalDate from) {
        sheets.lock(sheetId);
        LocalDate on = from != null ? from : sheets.today(sheetId);
        SettingValue saved = values.findBySheetIdAndKeyAndFrom(sheetId, key, on)
                .map(existing -> {
                    existing.setValue(value);
                    return existing;
                })
                .orElseGet(() -> new SettingValue(sheetId, key, on, value));
        saved = values.saveAndFlush(saved);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=" + key + " value="
                + (value != null ? (key.startsWith("terms") ? String.valueOf(value.intValue()) : value.toPlainString()) : "")
                + (from != null ? " from=" + from : ""));
        return saved;
    }

    /** Change the sheet's policy date; null leaves it blank (the sheet's today). */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String by, LocalDate policyDate) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=policy-date value="
                + (policyDate != null ? policyDate.toString() : ""));
        return saved;
    }

    /** Change the sheet's period numbering from; null leaves it blank (off). */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String by, LocalDate from) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=period-numbering-from value="
                + (from != null ? from.toString() : ""));
        return saved;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A value recorded for one of a sheet's dated settings (floor, late-pct, terms, terms-&lt;grade&gt;,
 *  clerk-limit, cap): in force from its from-date until the next one recorded for the key. Null only
 *  for the clerk limit or the cap, where it means none. */
@Entity
@Table(name = "sheet_setting_value")
public class SettingValue {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "setting_value", precision = 12, scale = 2)
    private BigDecimal value;

    protected SettingValue() {
    }

    public SettingValue(String sheetId, String key, LocalDate from, BigDecimal value) {
        this.sheetId = sheetId;
        this.key = key;
        this.from = from;
        this.value = value;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFrom() {
        return from;
    }

    public BigDecimal getValue() {
        return value;
    }

    public void setValue(BigDecimal value) {
        this.value = value;
    }
}

package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.person.PersonHold;

/** A claim a person on a sheet makes: an amount (two decimals), a date, a note and a status (DRAFT
 *  when added). A claim with a negative amount is a correction, naming the number of the SETTLED
 *  claim of the same person it corrects. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** When the claim was listed under its person, from the database's sequence: when it was added,
     *  or last reassigned. Claims are listed newest first by it; set by the database only. */
    @Column(name = "listed", insertable = false, updatable = false)
    private Long listed;

    @Column(name = "amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    /** The date the claim is due by, fixed when it was added: its date plus the terms of its person's
     *  grade in force on that date. It stays as it was when the terms or the claim's date change. */
    @Column(name = "due_by", nullable = false, updatable = false)
    private LocalDate dueBy;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The claim's number, given when it is opened and kept when it is voided (never reused): the
     *  sheet-wide number (1, 2, ...), or under period numbering <period>-<n> or X-<n>; null for a
     *  claim never opened. */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; null until then, or when its grade had no rate. */
    @Column(name = "settled_due", precision = 12, scale = 2)
    private BigDecimal settledDue;

    /** The user who opened the claim; null for a claim never opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Whether the person's last statement bound the claim to the figure it had then. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the claim was bound to by a statement; null when unbound or it had no figure. */
    @Column(name = "stated_due", precision = 12, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim this correction corrects; null for a claim that is not a correction. */
    @Column(name = "corrects_number")
    private String corrects;

    /** The date an OPEN claim is deferred until; null when it was never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
            String corrects) {
        this.sheetId = sheetId;
        this.dueBy = dueBy;
        this.corrects = corrects;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Move the claim to another person. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    /** Whether the claim is a correction: its amount is negative. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to a figure (may be null: it had none). */
    public void bind(BigDecimal due) {
        this.stated = true;
        this.statedDue = due;
    }

    /** Leave the claim unbound, its figure live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    /** Whether the claim is deferred on a day: it is OPEN and that day is before its deferred-until
     *  date. From that date on it is an OPEN claim like any other. */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today.isBefore(deferredUntil);
    }

    /** Whether the claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED ones do. */
    public boolean counts() {
        return status.counts();
    }

    /** Whether the claim is held: it is OPEN and dated within one of its person's holds. */
    public boolean heldBy(List<PersonHold> holds) {
        return status == ClaimStatus.OPEN && holds.stream().anyMatch(hold -> hold.contains(date));
    }

    /** Whether the claim counts in live totals on the sheet's today given its person's holds: one that
     *  counts and is not deferred, unless it is held and not bound by a statement (a bound claim stays
     *  in whatever its date). */
    public boolean countsLive(List<PersonHold> holds, LocalDate today) {
        return counts() && !deferredOn(today) && (stated || !heldBy(holds));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.NoSuchElementException;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonGradeService;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The claims people on a sheet make. */
@Service
public class ClaimService {

    /** Written for a due that has no rate to work from. */
    private static final String NO_RATE = "n/a";

    /** The name a claim's period number takes when its date falls in no period. */
    private static final String NO_PERIOD = "X";

    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final PersonRepository people;
    private final RateService rates;
    private final PersonGradeService grades;
    private final SheetService sheets;
    private final PeriodRepository periods;
    private final SettingService settings;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RateService rates,
            PersonGradeService grades, SheetService sheets, PeriodRepository periods, SettingService settings, Audit audit) {
        this.periods = periods;
        this.settings = settings;
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.rates = rates;
        this.grades = grades;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDesc(sheetId);
    }

    /** Add a claim for a person; a missing date takes the sheet's today. Its due-by is fixed now: its
     *  date plus the terms in force on that date for the person's grade then. A negative amount is a
     *  correction and must name a SETTLED claim of the person it corrects. */
    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Person person = person(sheetId, personId);
        corrects = numberOf(corrects);
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, on);
        refuseRetired(person, on);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        LocalDate dueBy = on.plusDays(settings.termsFor(sheetId, grades.gradeOn(personId, on), on));
        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), on, dueBy, noteOf(note),
                corrects));
        log(sheetId, user, person, added);
        record("CLAIM_ADDED", sheetId, user, person, added);
        return added;
    }

    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today. Any
     *  other claim is refused: an OPEN one is changed by voiding it and adding a new one. */
    @Transactional
    public Claim update(String sheetId, String user, Long personId, Long id, BigDecimal amount, LocalDate date,
            String note, String corrects) {
        Person person = person(sheetId, personId);
        corrects = numberOf(corrects);
        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimNotEditableException(claim.getStatus());
        }
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, on);
        refuseRetired(person, on);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        claim.setAmount(scaled(amount));
        claim.setCorrects(corrects);
        claim.setDate(on);
        claim.setNote(noteOf(note));
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_EDITED", sheetId, user, person, saved);
        return saved;
    }

    /** Move a claim to a new status; a change its status does not allow is refused, as is the user
     *  who opened a claim settling it. A clerk settling a claim whose due is above the clerk limit
     *  leaves it PENDING a steward's approval instead. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
        Person person = person(sheetId, personId);
        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
        // read below is its latest state.
        if (to == ClaimStatus.OPEN) {
            sheets.lock(sheetId);
        }
        Claim claim = claim(sheetId, personId, id);
        refuseClosed(sheetId, claim.getDate());
        if (!claim.getStatus().canMoveTo(to)) {
            throw new StatusChangeRefusedException(claim.getStatus(), to);
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new OwnClaimSettleRefusedException(user);
        }
        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
            throw new StatusChangeRefusedException(claim.getStatus(), to);
        }
        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
        // gathered by then.
        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
            to = ClaimStatus.PENDING;
        }
        claim.setStatus(to);
        if (to == ClaimStatus.OPEN) {
            claim.setNumber(nextNumber(sheetId, claim.getDate()));
            claim.setOpenedBy(user);
        } else if (to == ClaimStatus.SETTLED) {
            claim.setSettledDue(due);
        }
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        String event = switch (to) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
        };
        String line = line(event, sheetId, user, person, saved, saved.getNumber());
        if (to == ClaimStatus.SETTLED) {
            line += " due=" + settledDueText(saved);
        }
        audit.recordOnCommit(line);
        return saved;
    }

    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
     *  the claim counts in no total, is not overdue, cannot be settled and no statement binds it. A
     *  claim that is not OPEN, a date not after today, or a claim dated in a closed period, is refused. */
    @Transactional
    public Claim defer(String sheetId, String user, Long personId, Long id, LocalDate until) {
        Person person = person(sheetId, personId);
        Claim claim = claim(sheetId, personId, id);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new DeferRefusedException("A " + claim.getStatus() + " claim cannot be deferred");
        }
        if (!until.isAfter(sheets.today(sheetId))) {
            throw new DeferRefusedException("A claim is deferred to a date after the sheet's today");
        }
        claim.setDeferredUntil(until);
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(line("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber())
                + " until=" + until);
        return saved;
    }

    /** A steward approves a PENDING claim: it is SETTLED, its due frozen at this moment. Anyone else,
     *  the user who opened it, or a claim that is not PENDING, is refused. */
    @Transactional
    public Claim approve(String sheetId, String user, Long personId, Long id) {
        Person person = person(sheetId, personId);
        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.SETTLED);
        if (user.equals(claim.getOpenedBy())) {
            throw new OwnClaimSettleRefusedException(user);
        }
        claim.setSettledDue(dueOf(sheetId, person, claim));
        claim.setStatus(ClaimStatus.SETTLED);
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(line("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber())
                + " due=" + settledDueText(saved));
        return saved;
    }

    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by the person's
     *  last statement if that statement bound it. Anyone else, or a claim that is not PENDING, is
     *  refused. */
    @Transactional
    public Claim reject(String sheetId, String user, Long personId, Long id, String reason) {
        Person person = person(sheetId, personId);
        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.OPEN);
        claim.setStatus(ClaimStatus.OPEN);
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(line("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber())
                + " reason=" + reason.trim());
        return saved;
    }

    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
     *  one dated in a closed period, is refused. */
    @Transactional
    public Claim resettle(String sheetId, String user, Long personId, Long id) {
        Person person = person(sheetId, personId);
        Claim claim = claim(sheetId, personId, id);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResettleRefusedException(user);
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
        }
        refuseClosed(sheetId, claim.getDate());
        String old = settledDueText(claim);
        BigDecimal figure = liveFigureOf(sheetId, person, claim);
        claim.setSettledDue(figure == null ? null : figure.add(lateChargeOf(sheetId, claim, figure, true)));
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
                + " old=" + old + " new=" + settledDueText(saved));
        return saved;
    }

    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
     *  number and date, loses any figure a statement bound it to (live again until its new person's
     *  next statement), and is listed as its new person's newest claim. Anyone else, a SETTLED or VOID
     *  claim, a correction (it names a claim of its own person), a claim dated in a closed period, or
     *  a move to the same person or to one retired before the claim's date, is refused. */
    @Transactional
    public Claim reassign(String sheetId, String user, Long personId, Long id, Long toPersonId) {
        Person from = person(sheetId, personId);
        Person to = person(sheetId, toPersonId);
        Claim claim = claim(sheetId, personId, id);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ReassignRefusedException(user);
        }
        if (!claim.getStatus().canReassign()) {
            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
        }
        if (from.getId().equals(to.getId())) {
            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
        }
        if (claim.isCorrection()) {
            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
        }
        refuseClosed(sheetId, claim.getDate());
        refuseRetired(to, claim.getDate());
        claim.setPersonId(to.getId());
        claim.unbind();
        claims.saveAndFlush(claim);
        claims.relist(claim.getId());
        Claim saved = claim(sheetId, to.getId(), id);
        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
                + " from=" + from.getName() + " to=" + to.getName());
        return saved;
    }

    /** A claim's status log, oldest first: one line per status it has had. */
    public List<String> logOf(Long claimId) {
        return logs.findByClaimIdOrderByIdAsc(claimId).stream().map(ClaimLogEntry::text).toList();
    }

    /** The status logs of the sheet's claims by claim id, each oldest first. */
    public Map<Long, List<String>> logsOf(String sheetId) {
        return logs.findBySheetIdOrderByIdAsc(sheetId).stream().collect(Collectors.groupingBy(
                ClaimLogEntry::getClaimId, Collectors.mapping(ClaimLogEntry::text, Collectors.toList())));
    }

    /** Log the status a claim has just moved to (or been added in): by whom, on the sheet's today, and
     *  its due as it is now. */
    private void log(String sheetId, String user, Person person, Claim claim) {
        BigDecimal due = dueOf(sheetId, person, claim);
        logs.save(new ClaimLogEntry(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
                due != null ? due.toPlainString() : NO_RATE));
    }

    /** The PENDING claim a steward approves or rejects; refused when it is not PENDING, dated in a
     *  closed period, or the user is not a steward. */
    private Claim pending(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
        Claim claim = claim(sheetId, personId, id);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new StatusChangeRefusedException(claim.getStatus(), to);
        }
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ApprovalRefusedException(user);
        }
        return claim;
    }

    private Claim claim(String sheetId, Long personId, Long id) {
        return claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
    }

    private static String settledDueText(Claim claim) {
