355	
356	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by is
357	     *  before the sheet's today) or a correction, else the late percent of the figure for every full 30 days
358	     *  it is overdue (the late percent in force on the claim's date), rounded to two decimals as the claim's date decides (see roundingOf). Never bound by a statement: it follows the
359	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
360	     *  claim as if it were still OPEN. */
361	    private BigDecimal lateChargeOf(String sheetId, Claim claim, BigDecimal figure, boolean open) {
362	        BigDecimal none = BigDecimal.ZERO.setScale(2);
363	        if (!open || claim.isCorrection()) {
364	            return none;
365	        }
366	        long days = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId));
367	        if (days < 30) {
368	            return none;
369	        }
370	        return figure.multiply(settings.latePct(sheetId, claim.getDate())).multiply(BigDecimal.valueOf(days / 30))
371	                .movePointLeft(2).setScale(2, roundingOf(sheetId, claim));
372	    }
373	
374	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
375	     *  on the claim's date: amount times rate
376	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf), and at least the sheet's floor in force on its date unless it
377	     *  is a correction; null when no rate applies. */
378	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim) {
379	        BigDecimal amount = claim.getAmount();
380	        RoundingMode rounding = roundingOf(sheetId, claim);
381	        return rates.rateOn(sheetId, grades.gradeOn(person.getId(), claim.getDate()), claim.getDate())
382	                .map(Rate::getRate)
383	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
384	                .map(due -> claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate())))
385	                .orElse(null);
386	    }
387	
388	    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
389	     *  it corrects. */
390	    public LocalDate roundsBy(String sheetId, Claim claim) {
391	        if (!claim.isCorrection() || claim.getCorrects() == null) {
392	            return claim.getDate();
393	        }
394	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
395	                .map(Claim::getDate).orElse(claim.getDate());
396	    }
397	
398	    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
399	    private RoundingMode roundingOf(String sheetId, Claim claim) {
400	        return settings.roundingOn(sheetId, roundsBy(sheetId, claim));
401	    }
402	
403	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a due of n/a
404	     *  is within any limit, and a steward settles anything. */
405	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
406	        BigDecimal limit = settings.clerkLimit(sheetId);
407	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
408	            return false;
409	        }
410	        return settings.roleOf(sheetId, user) == Role.CLERK;
411	    }
412	
413	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
414	     *  any other amount names none. */
415	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
416	        if (amount.signum() >= 0) {
417	            if (corrects != null) {
418	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
419	            }
420	            return;
421	        }
422	        if (corrects == null) {
423	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
424	        }
425	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
426	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
427	        if (!settled) {
428	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
429	        }
430	    }
431	
432	    /** A claim dated inside a closed period cannot be added, edited, opened, settled or voided. */
433	    private void refuseClosed(String sheetId, LocalDate date) {
434	        if (periods.closedOn(sheetId, date)) {
435	            throw new PeriodClosedException("A claim dated " + date + " falls in a closed period");
436	        }
437	    }
438	
439	    /** A claim dated after its person's retirement date cannot be added or moved there. */
440	    private static void refuseRetired(Person person, LocalDate date) {
441	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
442	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
443	        }
444	    }
445	
446	    private Person person(String sheetId, Long personId) {
447	        return people.findByIdAndSheetId(personId, sheetId)
448	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
449	    }
450	
451	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
452	        record(event, sheetId, user, person, claim, claim.getNumber());
453	    }
454	
455	    /** One audit line about a claim; a claim with a number carries it at the end. */
456	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
457	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
458	    }
459	
460	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
461	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
462	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
463	                + (number != null ? " number=" + number : "");
464	    }
465	
466	    private static BigDecimal scaled(BigDecimal amount) {
467	        return amount.setScale(2, RoundingMode.UNNECESSARY);
468	    }
469	
470	    /** A claim number as typed: trimmed, null when blank. */
471	    private static String numberOf(String number) {
472	        return number == null || number.isBlank() ? null : number.trim();
473	    }
474	
475	    private static String noteOf(String note) {
476	        return note == null ? "" : note.trim();
477	    }
478	}
